var apiData = $input.first().json;
var newVersionId = apiData.versionId || '';
var updatedAt = apiData.updatedAt || new Date().toISOString();

// Oldingi versionId ni staticData dan ol
var globalData = $getWorkflowStaticData('global');
var savedVersionId = globalData.oxirgi_versionId || '';

// Sabab: qaysi trigger ishlaganiga qarab aniqlash
var sabab = 'qolda'; // Manual Start uchun default
try {
  var evtData = $('Event Trigger').first().json;
  sabab = evtData.sabab || 'publish';
} catch(e1) {
  try {
    $('Schedule — 6 soat').first();
    sabab = 'zaxira';
  } catch(e2) {}
}

// O'zgarish yo'q bo'lsa — to'xtat
if (savedVersionId && savedVersionId === newVersionId) {
  return [];
}

// O'zgarish bor — davom et
return [{ json: { sabab: sabab, newVersionId: newVersionId, updatedAt: updatedAt } }];

var list = $input.first().json.data || [];
var targets = [];
for (var i = 0; i < list.length; i++) {
  var wf = list[i];
  var nm = String(wf.name || '');
  var id = String(wf.id || '');
  if (id === '5kLZUkHJZpPBsYI6' || nm.indexOf('zb-') === 0) {
    var slug = nm.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
    if (id === '5kLZUkHJZpPBsYI6') slug = 'turk-kontent';
    targets.push({ json: { id: id, name: nm, slug: slug, path: 'kod/' + slug + '.json' } });
  }
}
return targets.length > 0 ? targets : [{ json: { id: '5kLZUkHJZpPBsYI6', name: 'turk kontent', slug: 'turk-kontent', path: 'kod/turk-kontent.json' } }];

var wfData = $input.first().json;
var batchItem = $('Har bir workflow uchun').item.json;
var nodes = wfData.nodes || [];
var connections = wfData.connections || {};
var isTurkKontent = batchItem.id === '5kLZUkHJZpPBsYI6';
var snap, b64;

// O'zgarish ma'lumotlari
var ozgarishData = {};
try { ozgarishData = $("O'zgarish tekshiruvi").first().json; } catch(e) {}

if (isTurkKontent) {
  // F0: turk-kontent uchun TO'LIQ eksport — barcha parametrlar, connections, nodeGroups, cred nomlari
  var fullNodes = {};
  for (var ni = 0; ni < nodes.length; ni++) {
    var nd = nodes[ni];
    var nc = nd.credentials || {};
    var credNames = {};
    for (var ct in nc) {
      if (nc[ct] && nc[ct].name) credNames[ct] = nc[ct].name;
    }
    fullNodes[nd.name] = {
      type: nd.type,
      typeVersion: nd.typeVersion,
      id: nd.id,
      position: nd.position,
      parameters: nd.parameters || {},
      onError: nd.onError || undefined,
      executeOnce: nd.executeOnce || undefined,
      alwaysOutputData: nd.alwaysOutputData || undefined,
      webhookId: nd.webhookId || undefined,
      creds: credNames
    };
  }
  snap = JSON.stringify({
    nodes: fullNodes,
    connections: connections,
    nodeGroups: wfData.groups || wfData.nodeGroups || [],
    settings: wfData.settings || {},
    versionId: wfData.versionId || ozgarishData.newVersionId || '',
    updatedAt: wfData.updatedAt || ozgarishData.updatedAt || new Date().toISOString(),
    vaqt: new Date().toISOString()
  }, null, 2);
} else {
  // zb- fayllari uchun cheklangan eksport
  var out = {};
  for (var zi = 0; zi < nodes.length; zi++) {
    var zn = nodes[zi];
    var zp = zn.parameters || {};
    var zt = String(zn.type || '');
    var ze = { turi: 'unknown' };
    var zc = zn.credentials || {};
    var zcn = {};
    for (var zct in zc) {
      if (zc[zct] && zc[zct].name) zcn[zct] = zc[zct].name;
    }
    if (zt.indexOf('code') > -1 && zp.jsCode) {
      ze = { turi: 'code', mode: zp.mode || 'runOnceForAllItems', kod: zp.jsCode };
    } else if (zt.indexOf('httpRequest') > -1) {
      ze = { turi: 'http', method: zp.method || 'GET', url: zp.url || '', body: zp.jsonBody || zp.body || '', sendBody: zp.sendBody || false };
    } else if (zt.indexOf('anthropic') > -1 || zt.indexOf('langchain') > -1) {
      var zo = zp.options || {};
      ze = { turi: 'ai', model: (zp.modelId && zp.modelId.value) || zp.model || '', maxTokens: zo.maxTokensToSample || zo.maxTokens || null, system: zo.systemMessage || zp.systemMessage || '' };
    } else if (zt.indexOf('telegram') > -1) {
      ze = { turi: 'telegram', text: zp.text || '', chatId: zp.chatId || '', thread: (zp.additionalFields || {}).message_thread_id || null };
    } else if (zt.indexOf('nodes-base.if') > -1) {
      ze = { turi: 'if', conditions: zp.conditions || {} };
    } else if (zt.indexOf('switch') > -1) {
      ze = { turi: 'switch', rules: (zp.rules && zp.rules.values) || [] };
    } else if (zt.indexOf('wait') > -1) {
      ze = { turi: 'wait', amount: zp.amount || 0, unit: zp.unit || 'seconds' };
    } else if (zt.indexOf('executeWorkflow') > -1) {
      ze = { turi: 'executeWorkflow', workflowId: (zp.workflowId && zp.workflowId.value) || '', inputs: zp.workflowInputs || {} };
    }
    if (Object.keys(zcn).length > 0) ze.creds = zcn;
    out[zn.name] = ze;
  }
  snap = JSON.stringify({ nodes: out, connections: connections, vaqt: new Date().toISOString() }, null, 2);
}

b64 = Buffer.from(snap, 'utf-8').toString('base64');
return [{ json: { b64: b64, vaqt: new Date().toISOString(), slug: batchItem.slug, path: batchItem.path, name: batchItem.name, isTurkKontent: isTurkKontent } }];

var sha = $input.first().json.sha || '';
var ext = $('Code va node extraction').first().json;

// Commit xabarini aniqlash
var commitMsg;
if (ext.isTurkKontent) {
  var ozData = {};
  try { ozData = $("O'zgarish tekshiruvi").first().json; } catch(e) {}
  var sabab = ozData.sabab || 'qolda';
  var versionId = ozData.newVersionId || '';
  var shortVid = versionId ? versionId.replace(/-/g, '').slice(0, 8) : ext.vaqt.slice(0, 10);
  commitMsg = 'turk-kontent ' + shortVid + ' · ' + sabab;
} else {
  commitMsg = 'kod snapshot ' + ext.slug + ' ' + ext.vaqt;
}

var body = { message: commitMsg, content: ext.b64 };
if (sha) body.sha = sha;
return [{ json: { body: body, path: ext.path, vaqt: ext.vaqt } }];

// Faqat turk-kontent uchun staticData ni yangilaymiz
var ext = {};
try { ext = $('Code va node extraction').first().json; } catch(e) {}
if (ext.isTurkKontent) {
  var ozData = {};
  try { ozData = $("O'zgarish tekshiruvi").first().json; } catch(e) {}
  var newVid = ozData.newVersionId || '';
  if (newVid) {
    var globalData = $getWorkflowStaticData('global');
    globalData.oxirgi_versionId = newVid;
  }
}
return $input.all();

